##### Python

::: {#5c0f2ad1 .cell execution_count=24}
``` {.python .cell-code}
def ids1370_brute(s):
    pool = sorted(s)
    res = []
    while pool:
        last, pick = "", []
        for ch in pool:
            if ch > last:
                pick.append(ch); last = ch
        res += pick
        for ch in pick:
            pool.remove(ch)
        last, pick = "{", []
        for ch in reversed(pool):
            if ch < last:
                pick.append(ch); last = ch
        res += pick
        for ch in pick:
            pool.remove(ch)
    return "".join(res)
```
