def ids1370_count(s):
    freq = [0] * 26
    for ch in s:
        freq[ord(ch) - 97] += 1
    res = []
    n = len(s)
    while len(res) < n:
        for i in range(26):
            if freq[i]:
                res.append(chr(97 + i)); freq[i] -= 1
        for i in range(25, -1, -1):
            if freq[i]:
                res.append(chr(97 + i)); freq[i] -= 1
    return "".join(res)

