def fad448_sign(nums):
    n = len(nums)
    a = list(nums)
    for x in nums:
        idx = abs(x) - 1
        if a[idx] > 0:
            a[idx] = -a[idx]
    return [i + 1 for i in range(n) if a[i] > 0]

for _ in range(400):
